cat /home/ubuntu/.claude-account-4/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-8-projects-acr-vla-conformal-refinement--claude-sessions-agent-142c5ba1/e866adbd-436e-45a5-ba7d-85ce781144d6/tool-results/mcp-agent-ml-research-read_registry-1779927197613.txt | python3 -c "
import json, sys
data = json.load(sys.stdin)
result = json.loads(data['result'])
exps = result['data']['experiments']
# Find all tau-sweep Long experiments for comparison
long_tau = {}
for k, v in exps.items():
    if 'tau' in k and 'long' in k and 'smolvla' in k and v.get('status') == 'DONE':
        metrics = v.get('metrics', {})
        conclusion = v.get('conclusion', '')
        hypothesis = v.get('hypothesis', '')
        long_tau[k] = {
            'conclusion': conclusion,
            'metrics': metrics,
            'hypothesis': hypothesis[:120]
        }
# Also get VLA-only Long baseline
for k, v in exps.items():
    if 'vla-only' in k and 'long' in k and v.get('status') == 'DONE' and v.get('conclusion') == 'success':
        metrics = v.get('metrics', {})
        long_tau[k] = {
            'conclusion': v.get('conclusion', ''),
            'metrics': metrics,
            'hypothesis': v.get('hypothesis', '')[:120]
        }
# Also get CRM always-on Long
for k, v in exps.items():
    if 'crm-always-on-long' in k and v.get('status') == 'DONE':
        metrics = v.get('metrics', {})
        long_tau[k] = {
            'conclusion': v.get('conclusion', ''),
            'metrics': metrics,
            'hypothesis': v.get('hypothesis', '')[:120]
        }

print(json.dumps(long_tau, indent=2, ensure_ascii=False))
